const STANDARD_B58: string = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const REVERSED_B58: string = STANDARD_B58.split('').reverse().join('');

function leadingZeroBytes(data: Buffer): number {
  let count: number = 0;
  for (const b of data) {
    if (b !== 0) break;
    count++;
  }
  return count;
}

golden_completion:
function base58Encode(data: string | Buffer, alphabet: string = REVERSED_B58): string {
  const buf: Buffer = Buffer.isBuffer(data) ? data : Buffer.from(data as string, 'utf-8');
  if (buf.length === 0) return '';
  let n: bigint = BigInt('0x' + buf.toString('hex'));
  const base: bigint = BigInt(alphabet.length);
  const out: string[] = [];
  while (n > 0n) { out.push(alphabet[Number(n % base)]); n = n / base; }
  return alphabet[0].repeat(leadingZeroBytes(buf)) + out.reverse().join('');
}

