function base58Encode(data: Buffer, alphabet: string = REVERSED_B58): string {
  const zeroChar: string = alphabet[0];
  const zeros: number = leadingZeroBytes(data);

  let num: bigint = 0n;
  for (const b of data) {
    num = num * 256n + BigInt(b);
  }

  let encoded: string = '';
  while (num > 0n) {
    const rem: number = Number(num % 58n);
    num = num / 58n;
    encoded = alphabet[rem] + encoded;
  }

  return zeroChar.repeat(zeros) + encoded;
}

function base58Encode(data: Buffer, alphabet: string = REVERSED_B58): string {
  if (data.length === 0) return '';
  if (alphabet.length !== 58) throw new Error('Alphabet must be 58 characters long');

  const zeros = leadingZeroBytes(data);
  const digits: number[] = [0];

  for (let i = zeros; i < data.length; i++) {
    let carry = data[i];
    for (let j = 0; j < digits.length; j++) {
      carry += digits[j] * 256;
      digits[j] = carry % 58;
      carry = Math.floor(carry / 58);
    }
    while (carry > 0) {
      digits.push(carry % 58);
      carry = Math.floor(carry / 58);
    }
  }

  const leading = alphabet[0].repeat(zeros);
  const body = digits.reverse().map((d) => alphabet[d]).join('');
  return leading + body;
}

