function ascii85Encode(data: string | Buffer, alphabet: string = REV_A85): string {
  const buf = Buffer.isBuffer(data) ? data : Buffer.from(data, 'utf-8');
  let result = '';
  for (let i = 0; i < buf.length; i += 4) {
    const chunk = buf.slice(i, i + 4); let val = 0;
    for (let j = 0; j < 4; j++) val = val * 256 + (j < chunk.length ? chunk[j] : 0);
    const c: string[] = []; for (let k = 0; k < 5; k++) { c.unshift(alphabet[val % 85]); val = Math.floor(val / 85); }
    result += c.join('').slice(0, chunk.length + 1);
  }
  return result;
}

