// Tokenize a simple expression language into typed tokens.
// Token types: 'num', 'str', 'op', 'ident', 'paren'
// Numbers: integer sequences (e.g. '42', '0')
// Strings: double-quoted with backslash escapes (\" and \\)
// Operators: +, -, *, /, ==, !=, >=, <=, >, <
// Identifiers: [a-zA-Z_][a-zA-Z0-9_]*
// Parens: ( and )
// Whitespace is skipped.
// CRITICAL: Multi-char operators (==, !=, >=, <=) must be parsed as ONE token.
//
// tokenize('x + 42') => [{type:'ident',val:'x'},{type:'op',val:'+'},{type:'num',val:'42'}]

interface Token { type: string; val: string; }

golden_completion:
function tokenize(input: string): Token[] {
  const t: Token[] = []; let i = 0;
  while (i < input.length) {
    if (/\s/.test(input[i])) { i++; continue; }
    if (/[0-9]/.test(input[i])) { let n=''; while(i<input.length&&/[0-9]/.test(input[i]))n+=input[i++]; t.push({type:'num',val:n}); continue; }
    if (input[i]==='"') { let s='',j=i+1; while(j<input.length&&input[j]!=='"'){if(input[j]==='\\'){s+=input[++j];}else s+=input[j];j++;} t.push({type:'str',val:s});i=j+1;continue; }
    const d=input.slice(i,i+2); if(['==','!=','>=','<='].includes(d)){t.push({type:'op',val:d});i+=2;continue;}
    if('+-*/<>'.includes(input[i])){t.push({type:'op',val:input[i++]});continue;} if('()'.includes(input[i])){t.push({type:'paren',val:input[i++]});continue;}
    if(/[a-zA-Z_]/.test(input[i])){let id='';while(i<input.length&&/[a-zA-Z0-9_]/.test(input[i]))id+=input[i++];t.push({type:'ident',val:id});continue;} i++;
  }
  return t;
}

