function* rangeGenerator(options: RangeOptions): Generator<number> {
  const { start, end } = options;
  let step = options.step ?? (end < start ? -1 : 1);
  const inclusive = options.inclusive ?? true;

  if (step === 0) throw new Error('step must not be 0');

  if (start === end) {
    if (inclusive) yield start;
    return;
