import * as assert from 'assert';

interface Action {
  type: string;
  payload?: any;
}

type Reducer<S> = (state: S, action: Action) => S;
type Middleware<S> = (state: S, action: Action, next: (a: Action) => S) => S;

// A store that applies middleware before the reducer.
// Middleware can modify the action, skip it, or dispatch new actions.

golden_completion:
function createStore<S>(reducer: Reducer<S>, initial: S, middlewares: Middleware<S>[] = []): {
  getState: () => S;
  dispatch: (action: Action) => S;
} {
  let state = initial;
  const dispatch = (action: Action): S => {
    const chain = middlewares.reduceRight(
      (next: (a: Action) => S, mw: Middleware<S>) => (a: Action) => mw(state, a, next),
      (a: Action) => { state = reducer(state, a); return state; }
    );
    return chain(action);
  };
  return { getState: () => state, dispatch };
}

