assert.deepStrictEqual(r2, { items: [1, 2, 3, 4] });

// Prepend strategy: target + source
const r3 = mergeConfig(
  { items: [1, 2] },
  { items: [3, 4] },
  { arrayStrategy: 'prepend', depth: 1 }
);
assert.deepStrictEqual(r3, { items: [3, 4, 1, 2] });

// Unique strategy: deduplicate
const r4 = mergeConfig(
  { tags: ['a', 'b'] },
  { tags: ['b', 'c'] },
  { arrayStrategy: 'unique', depth: 1 }
);
assert.deepStrictEqual(r4, { tags: ['a', 'b', 'c'] });

