);
assert.deepStrictEqual(r5, { nested: { a: 10 } }); // shallow: target replaces entirely

// Depth 1: recursive merge
const r6 = mergeConfig(
  { nested: { a: 1, b: 2 } },
  { nested: { a: 10 } },
  { arrayStrategy: 'replace', depth: 1 }
