interface TurnstileCtx { coins: number; passes: number; }

const turnstile = createMachine<TurnstileCtx>(
  [
    { from: 'locked', to: 'unlocked', event: 'COIN',
      action: (ctx) => { ctx.coins++; } },
    { from: 'unlocked', to: 'locked', event: 'PUSH',
      action: (ctx) => { ctx.passes++; } },
    { from: 'locked', to: 'locked', event: 'PUSH' },  // no-op push on locked
  ],
  'locked',
  { coins: 0, passes: 0 }
);

let r = turnstile.send('COIN');
assert.strictEqual(r.state, 'unlocked');
assert.strictEqual(r.context.coins, 1);

r = turnstile.send('PUSH');
assert.strictEqual(r.state, 'locked');
assert.strictEqual(r.context.passes, 1);

// Push on locked: stays locked, no action
r = turnstile.send('PUSH');
assert.strictEqual(r.state, 'locked');
assert.strictEqual(r.context.passes, 1);

assert.deepStrictEqual(r.history, ['locked', 'unlocked', 'locked', 'locked']);

assertions:
// Guard conditions
interface DoorCtx { keyCard: boolean; attempts: number; }
const door = createMachine<DoorCtx>(
  [
    { from: 'closed', to: 'open', event: 'OPEN',
      guard: (ctx) => ctx.keyCard,
      action: (ctx) => { ctx.attempts++; } },
    { from: 'closed', to: 'closed', event: 'OPEN',
      guard: (ctx) => !ctx.keyCard,
      action: (ctx) => { ctx.attempts++; } },
    { from: 'open', to: 'closed', event: 'CLOSE' },
  ],
  'closed',
  { keyCard: false, attempts: 0 }
);

// Without keyCard: guard blocks open
let dr = door.send('OPEN');
assert.strictEqual(dr.state, 'closed');
assert.strictEqual(dr.context.attempts, 1);

// Unknown event: no change
dr = door.send('UNKNOWN');
assert.strictEqual(dr.state, 'closed');
assert.strictEqual(dr.context.attempts, 1);

// After getting keyCard
dr.context.keyCard = true; // does NOT affect internal context (it's a copy)
// We need to test with a fresh machine
const door2 = createMachine<DoorCtx>(
  [
    { from: 'closed', to: 'open', event: 'OPEN',
      guard: (ctx) => ctx.keyCard },
    { from: 'open', to: 'closed', event: 'CLOSE' },
  ],
  'closed',
  { keyCard: true, attempts: 0 }
);
const dr2 = door2.send('OPEN');
assert.strictEqual(dr2.state, 'open');

