function createMachine<C>(
  transitions: Transition<C>[],
  initialState: string,
  initialContext: C
) {
  let state = initialState;
  const context = initialContext;
  const history: string[] = [initialState];

  return {
    send(event: string): MachineResult<C> {
      const candidates = transitions.filter(t => t.from === state && t.event === event);

      let chosen: Transition<C> | undefined;
      for (const t of candidates) {
        if (!t.guard || t.guard(context)) {
          chosen = t;
          break;
        }
      }

      if (chosen) {
        chosen.action?.(context);
        state = chosen.to;
        history.push(state);
      }

      return { state, context, history: [...history] };
    }
  };
}
function createMachine<C>(
  transitions: Array<Transition<C>>,
  initialState: string,
  initialContext: C
) {
