  let context = initialContext;
  const history: string[] = [initialState];

  return {
    send: (event: string): MachineResult<C> => {
      const candidates = transitions.filter(
        (t) => t.from === state && t.event === event
      );

      const matches = candidates.filter((t) => (t.guard ? t.guard(context) : true));
      const chosen = matches[0];

      if (!chosen) {
        return { state, context, history: [...history] };
      }

      if (chosen.action) chosen.action(context);
      state = chosen.to;
      history.push(state);

      return { state, context, history: [...history] };
    },
  };
}
